set_time_limit(120);
$base = __DIR__;
$errors = [];
$ok = [];

function writeFile($base, $rel, $gz_b64) {
    $dir = dirname($base . "/" . $rel);
    if (!is_dir($dir)) mkdir($dir, 0755, true);
    $data = gzdecode(base64_decode($gz_b64));
    return file_put_contents($base . "/" . $rel, $data) !== false;
}

